namespace ModernLibs.FileHelpers.Generator.Models;

/// <summary>
/// Equatable pipeline model representing a single annotated record type.
/// Contains ONLY primitives and EquatableArray — no ISymbol, SyntaxNode, or Compilation references.
/// This is a C# record: structural equality is auto-generated by the compiler.
/// </summary>
internal sealed record RecordModel(
    string Namespace,
    string TypeName,
    string TypeKind,
    bool IsReadOnly,
    string RecordKind,
    string Delimiter,
    EquatableArray<FieldModel> Fields);
